        const copy=mon=>({uid:mon.uid,src:mon.src||mon.uid,id:mon.id,level:Math.min(100,Number(mon.level)||1),shiny:!!mon.shiny,...mon.rank?{rank:mon.rank}:{},...mon.taste?{taste:mon.taste}:{},reg:monRegion(mon)});
