            const expected=row.members.reduce((n,id)=>n+(CHAPTERS.get(id).shinyPools?.[phase]||[]).filter(([mon])=>mon===target).reduce((n,[,best,clear])=>n+(clear||best*.15),0),0);
            return{...row,expected,rate:expected/Math.max(20,row.units*2.8/2.5)*60};
