        const owned=[...(s.mons||[]),...(s.pension?.mons||[]).map(row=>row.mon),...(s.under?.slots||[]).flatMap(row=>row.mons||[]),
            ...(s.link?.stash?.mons||[]),s.tradeOut?.mon,s.tradeIn?.mon,...(s.mktOut||[]).map(row=>row.mon)].filter(Boolean);
