            const id=Object.keys(DATA.automation.buffs).filter(id=>DATA.automation.buffs[id].family===family&&s.items?.[id]>0).sort((a,b)=>(DATA.automation.buffs[b].mult||0)-(DATA.automation.buffs[a].mult||0))[0];
